String chartSymbol(){return chartMarketSpinner==null||chartMarketSpinner.getSelectedItem()==null?"":chartMarketSpinner.getSelectedItem().toString();}
void loadChart(){
if(chartView==null||chartSymbol().isEmpty()){if(chartStatus!=null)chartStatus.setText("Waiting for Arcus market list…");return;}
final String symbol=chartSymbol(),tf=chartTfSpinner.getSelectedItem().toString();chartStatus.setText("Loading "+symbol+" · "+tf+" candles…");
new Thread(()->{HttpURLConnection c=null;try{
long to=System.currentTimeMillis()*1000L;URL u=new URL("https://api.arcus.xyz/v1/candles?market="+java.net.URLEncoder.encode(symbol,"UTF-8")+"&timeframe="+tf+"&to="+to+"&countback=180");
c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("Accept","application/json");
int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);
if(code<200||code>=300)throw new Exception("Arcus API HTTP "+code+": "+out.toString("UTF-8"));
JSONObject response=new JSONObject(out.toString("UTF-8"));JSONArray arr=response.optJSONArray("candles");if(arr==null)throw new Exception("No candles field in Arcus response");
ArrayList<ChartView.Candle> candles=new ArrayList<>();for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null)continue;try{candles.add(new ChartView.Candle(o.optLong("openTime"),Double.parseDouble(o.getString("open")),Double.parseDouble(o.getString("high")),Double.parseDouble(o.getString("low")),Double.parseDouble(o.getString("close"))));}catch(Exception ignored){}}
Collections.sort(candles,(a,b1)->Long.compare(a.time,b1.time));if(candles.isEmpty())throw new Exception("No candle data returned");
runOnUiThread(()->{chartView.setCandles(candles);chartStatus.setText(symbol+" · "+tf+" · "+candles.size()+" candles · Move crosshair and press + to add alert");updateChartAlertLines();});
}catch(Exception e){String msg=e.getMessage()==null?"Chart loading failed":e.getMessage();runOnUiThread(()->chartStatus.setText("Chart error: "+msg));}finally{if(c!=null)c.disconnect();}}).start();
}
void addChartAlert(double price){
String symbol=chartSymbol();if(symbol.isEmpty()||price<=0)return;
new AlertDialog.Builder(this).setTitle("Add Alert").setMessage(symbol+"\\nTarget price: "+String.format(Locale.US,"%.8f",price))
.setNegativeButton("Cancel",null).setPositiveButton("Add Alert",(d,w)->{try{JSONArray a=levels();JSONObject o=new JSONObject();o.put("symbol",symbol);o.put("price",price);o.put("mode",1);o.put("created",System.currentTimeMillis());o.put("enabled",true);a.put(o);save(a);updateChartAlertLines();Toast.makeText(this,"Alert added at "+price,Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not save alert",Toast.LENGTH_SHORT).show();}}).show();
}

void updateChartAlertLines(){if(chartView==null)return;ArrayList<Double> prices=new ArrayList<>();JSONArray a=levels();String sym=chartSymbol();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optBoolean("enabled",true)&&sym.equalsIgnoreCase(o.optString("symbol")))prices.add(o.optDouble("price",0));}chartView.setAlertPrices(prices);}
void showChartAlertActions(int chartIndex){try{JSONArray a=levels();String sym=chartSymbol();int found=-1,n=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optBoolean("enabled",true)&&sym.equalsIgnoreCase(o.optString("symbol"))){if(n==chartIndex){found=i;break;}n++;}}if(found<0)return;final int index=found;new AlertDialog.Builder(this).setTitle("Chart alert").setItems(new String[]{"Edit alert","Delete alert"},(d,w)->{if(w==0)editLevel(index);else{JSONArray old=levels(),next=new JSONArray();for(int i=0;i<old.length();i++)if(i!=index)next.put(old.opt(i));save(next);renderLevels();updateChartAlertLines();}}).setNegativeButton("Cancel",null).show();}catch(Exception ignored){}}
void moveChartAlert(int chartIndex,double price){try{JSONArray a=levels();String sym=chartSymbol();int found=-1,n=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optBoolean("enabled",true)&&sym.equalsIgnoreCase(o.optString("symbol"))){if(n==chartIndex){found=i;break;}n++;}}if(found<0)return;JSONObject o=a.getJSONObject(found);o.put("price",price);o.put("created",System.currentTimeMillis());a.put(found,o);save(a);updateChartAlertLines();Toast.makeText(this,"Alert moved to "+String.format(Locale.US,"%.6f",price),Toast.LENGTH_SHORT).show();}catch(Exception ignored){}}
